INSERT INTO vocabularies (jmdict_id, jlpt_level, word, reading, romaji, han_viet, part_of_speech, meaning, example_sentence, example_furigana, example_meaning)
VALUES ('1331840', 'N3', '州', 'しゅう', 'shuu', 'CHÂU', 'Danh từ', 'tiểu bang (của Hoa Kỳ, Úc, Ấn Độ, Đức, v.v.); tỉnh (ví dụ: Canada); quận (ví dụ: Vương quốc Anh); khu vực (ví dụ: Ý)', '南部の州へ冬期に旅行すると、今旅行するよりも料金が高くなります。', '{南部|なんぶ}の{州|しゅう}へ{冬期|とうき}に{旅行|りょこう}すると、{今|いま}{旅行|りょこう}するよりも{料金|りょうきん}が{高|たか}くなります。', 'Du lịch đến các bang miền Nam vào mùa đông sẽ đắt hơn hiện nay.');
