INSERT INTO vocabularies (jmdict_id, jlpt_level, word, reading, romaji, han_viet, part_of_speech, meaning, example_sentence, example_furigana, example_meaning)
VALUES ('1580510', 'N1', '情緒', 'じょうしょ', 'jousho', 'TÌNH TỰ', 'Danh từ, Tính từ bổ nghĩa (no)', 'cảm xúc; cảm giác', 'そのような情緒と行動の分離に比べれば、破局的結果の方がまだましである。', NULL, 'Thậm chí thảm họa còn tốt hơn sự tách biệt giữa cảm xúc và hành động như vậy.');
